-- Table shapes from DEV 2026-09-16, without any user records.
create type public.metodo_pago_enum as enum ('Transferencia bancaria','Efectivo','Tarjeta en plataforma','Depósito a cuenta','Otro','Cheque');
create type public.payment_request_type as enum ('provider_payment','reimbursement','deposit_refund','other','cash','check','online_purchase','nomina','convenio');
create type public.payment_request_status as enum ('draft','submitted','pending_approval','approved','rejected','changes_requested','finance_validation','scheduled','paid','cancelled');
create table public.approval_rules (id uuid primary key default gen_random_uuid(), role_id uuid, company_id uuid, cost_center_id uuid, amount_min numeric, amount_max numeric, approval_level integer, can_approve boolean, can_reject boolean, can_request_changes boolean, can_approve_exception boolean, can_request_budget_adjustment boolean, active boolean, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table public.approver_assignments (id uuid primary key default gen_random_uuid(), company_id uuid, requester_id uuid, approver_id uuid, created_at timestamp with time zone default now(), active boolean, created_by uuid, updated_at timestamp with time zone default now());
create table public.budget_categories (id uuid primary key default gen_random_uuid(), code text, name text, category text, budget_type text, active boolean, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), no_presupuestal boolean);
create table public.companies (id uuid primary key default gen_random_uuid(), name text, legal_name text, rfc text, active boolean, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table public.cost_centers (id uuid primary key default gen_random_uuid(), name text, code text, area text, active boolean, notes text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table public.payment_request_approvals (id uuid primary key default gen_random_uuid(), payment_request_id uuid, actor_profile_id uuid, role_id uuid, action text, from_status text, to_status text, comments text, approval_level integer, budget_decision_snapshot text, budget_block_reason_snapshot text, budget_result_snapshot jsonb, created_at timestamp with time zone default now());
create table public.payment_requests (id uuid primary key default gen_random_uuid(), provider_id uuid, provider_bank_account_id uuid, celebration_event_id uuid, production_event_id uuid, cost_center_id uuid, request_type payment_request_type, requested_by uuid, approved_by uuid, validated_by uuid, paid_by uuid, amount_requested numeric(14,2), currency text, exchange_rate numeric(14,6), requires_invoice boolean, invoice_received boolean, company_bank_account_id uuid, status payment_request_status, due_date date, scheduled_payment_date date, paid_at timestamp with time zone, concept text, notes text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), company_id uuid, proveedor_id uuid, budget_category_id uuid, budget_month date, budget_decision text, budget_block_reason text, budget_available_before numeric(14,2), budget_available_after numeric(14,2), budget_shortfall numeric(14,2), budget_checked_at timestamp with time zone, is_extraordinary_adjustment boolean, request_number text, description text, submitted_at timestamp with time zone, budget_result jsonb, exception_status text, exception_action text, exception_reason text, exception_approved_by uuid, exception_approved_at timestamp with time zone, requires_budget_adjustment boolean, operational_comments text, payment_reference text, payment_concept text, scheduled_by uuid, scheduled_at timestamp with time zone, approved_at timestamp with time zone, invoice_storage_path text, payment_method text, approver_id uuid, approver_assignment_id uuid, approver_selection_source text, approval_material_updated_at timestamp with time zone default now(), extraordinary_state text, extraordinary_requested_by uuid, extraordinary_requested_at timestamp with time zone, extraordinary_intent_cancelled_by uuid, extraordinary_intent_cancelled_at timestamp with time zone, payroll_subtype text, payroll_period_start date, payroll_period_end date, subtotal_amount numeric, tax_amount numeric, withholding_amount numeric, invoice_uuid text, cfdi_data jsonb, beneficiary_profile_id uuid, project_id uuid, partida_unsure boolean, no_presupuestal boolean);
create table public.profiles (id uuid primary key default gen_random_uuid(), auth_user_id uuid, full_name text, email text, phone text, active boolean, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table public.proveedores (id uuid primary key default gen_random_uuid(), alias text, nombre_completo text, metodo_pago metodo_pago_enum, tipo_cuenta text, clabe text, cuenta_bancaria text, banco text, es_personal_eventual boolean, csf_url text, acta_constitutiva_url text, identificacion_url text, comprobante_domicilio_url text, estado_cuenta_url text, creado_por text, creado_el timestamp with time zone, airtable_alias text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), rfc text, email text, telefono text, tipo_proveedor text, notas text, activo boolean, destination_type text, convenio_number text, beneficiary_name text, csf_file_path text, csf_uploaded_at timestamp with time zone, csf_uploaded_by uuid, persona_tipo text);
create table public.reimbursement_items (id uuid primary key default gen_random_uuid(), payment_request_id uuid, budget_category_id uuid, descripcion text, amount numeric, subtotal_amount numeric, tax_amount numeric, deducible boolean, invoice_uuid text, cfdi_data jsonb, storage_path text, created_at timestamp with time zone default now(), company_id uuid);
create table public.roles (id uuid primary key default gen_random_uuid(), name text, description text);
create table public.user_roles (id uuid primary key default gen_random_uuid(), profile_id uuid, role_id uuid, created_at timestamp with time zone default now());
